frappe.ui.form.on('Minutes Of The Meeting', {
    validate: function(frm) {
        let signed = 0;
        let unsigned = 0;

        const rows = frm.doc.minutes_meeting_listname_table || [];

        rows.forEach(row => {
            if (row.signature && row.signature.startsWith("data:image")) {
                signed++;
            } else {
                unsigned++;
            }
        });

        frm.set_value('qty_attendees', signed);
        frm.set_value('qty_meeting_leave', unsigned);
    }
});


