frappe.ui.form.on('Minutes Of The Meeting', {
    onload: function(frm) {
        set_fiscal_year(frm);
    },
    refresh: function(frm) {
        if (!frm.doc.fiscal_year) {
            set_fiscal_year(frm);
        }
    }
});

function set_fiscal_year(frm) {
    const buddhist_year = new Date().getFullYear() + 543;

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Annual Rights",
            filters: {
                name: buddhist_year.toString()
            },
            fields: ["name"]
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                frm.set_value('fiscal_year', r.message[0].name);
            }
        }
    });
}


