// เมื่อเลือกแผนกแล้ว ดึงรายชื่อในแผนกทั้งหมดมาแสดง Auto
frappe.ui.form.on("Minutes Of The Meeting", {
    department_meeting(frm) {
        if (!frm.doc.department_meeting) return;

        // เคลียร์ตารางเก่า
        frm.clear_table("minutes_meeting_listname_table");

        // ดึงข้อมูล Personnel ที่อยู่ในแผนกที่เลือก
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Personnel",
                filters: {
                    department: frm.doc.department_meeting
                },
                fields: ["name", "fullname", "job_position"] // ✅ ตรวจสอบว่าฟิลด์นี้มีจริง
            },
            callback(r) {
                if (r.message && r.message.length > 0) {
                    r.message.forEach(p => {
                        let row = frm.add_child("minutes_meeting_listname_table");
                        row.fullname = p.fullname; // ✅ แสดงชื่อจริง
                        row.position = p.job_position;
                    });
                    frm.refresh_field("minutes_meeting_listname_table");
                }
            }
        });
    }
});

frappe.ui.form.on('Minutes Of The Meeting', {
