                    // ถ้าเซ็นแล้ว → ใส่วันที่วันนี้
                    frm.set_value('minutes_reviewer_date', frappe.datetime.get_today());
                } else {
                    // ถ้าลบลายเซ็น → เคลียร์วันที่
                    frm.set_value('minutes_reviewer_date', null);
                }
            });
        }
